@APP.get("/courses")
def courses():
    parts={}
    for l in COURSE: parts.setdefault(l["part"],[]).append(l)
    blocks=""
    for p,ls in parts.items():
        items="".join(f'<a class="lesson" href="/learn/{l["n"]}"><span><span class="eyebrow">Lesson {l["n"]}</span><br><strong>{l["title"]}</strong></span><span>→</span></a>' for l in ls)
        blocks+=f'<section class="section"><div class="eyebrow">{p}</div><h2>{len(ls)} lessons</h2><div class="lessonlist">{items}</div></section>'
    return layout(f'<section class="course"><div class="eyebrow">Course library</div><h1 style="font-size:60px">The Ultimate<br>Python Course</h1><p>Start at the beginning or jump straight into a topic.</p></section>{blocks}',"Courses")

@APP.get("/learn/<int:n>")
def learn(n):
    if n<1 or n>len(COURSE): abort(404)
    l=COURSE[n-1]; u=user(); done=False
    if u:
        con=db(); done=bool(con.execute("SELECT completed FROM progress WHERE user_id=? AND lesson_id=?",(u["id"],n)).fetchone()); con.close()
    nextn=n+1 if n<len(COURSE) else None
    safe_body=html.escape(l["body"])
    js=f"""<script src="https://cdn.jsdelivr.net/pyodide/v0.27.7/full/pyodide.js"></script><script>
let py; async function boot(){{document.getElementById('run').disabled=true;document.getElementById('run').textContent='Loading Python…';py=await loadPyodide();document.getElementById('run').disabled=false;document.getElementById('run').textContent='Run code';}}
async function runCode(){{const out=document.getElementById('out'), code=document.getElementById('code').value;out.textContent='Running…';try{{await py.runPythonAsync("import sys,io\nsys.stdout=io.StringIO()\nsys.stderr=io.StringIO()");await py.runPythonAsync(code);out.textContent=py.runPython("sys.stdout.getvalue()")}} catch(e){{out.textContent=String(e)}}}}
async function complete(){{const r=await fetch('/api/progress/{n}',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{csrf:'{csrf()}'}})}});if(r.ok)location.reload();}}
boot();</script>"""
    code = re.findall(r'(?s)(?:(?:^|\n))(?:[a-zA-Z_].*?\n)?',l["body"])[:1]
    starter = "print('Hello, Python!')"
    if "def " in l["body"]: starter="def is_even(n):\n    return n % 2 == 0\n\nprint(is_even(10))"
    elif "for " in l["body"]: starter="for i in range(5):\n    print(i)"
    elif "class " in l["body"]: starter="class Dog:\n    def __init__(self, name):\n        self.name = name\n\nprint(Dog('Rex').name)"
    c=f"""<section class="lessonpage"><a class="muted" href="/courses">← All courses</a><div style="margin-top:30px" class="eyebrow">{l["part"]}</div><h1 style="font-size:56px">Chapter {l["n"]}: {l["title"]}</h1><div class="lessonbody">{safe_body}</div>
<div class="play"><div class="eyebrow">Interactive Python playground</div><h2>Try it yourself</h2><p>Runs in your browser. Nothing you execute here is sent to the backend.</p><textarea id="code">{starter}</textarea><div class="actions"><button id="run" class="solid" onclick="runCode()" disabled>Loading Python…</button>{f'<button onclick="complete()">✓ Mark complete</button>' if u else '<a class="pill" href="/login">Log in to save progress</a>'}</div><div id="out" class="output">Output will appear here.</div></div>
<div class="actions"><a class="pill" href="/courses">Course index</a>{f'<a class="pill solid" href="/learn/{nextn}">Next lesson →</a>' if nextn else ''}</div></section>{js}"""
    return layout(c,f'Chapter {n}: {l["title"]}')

@APP.post("/api/progress/<int:n>")
def progress(n):
    u=user()
    if not u or n<1 or n>len(COURSE): return jsonify(error="unauthorized"),401
    data=request.get_json(silent=True) or {}
    if not secrets.compare_digest(str(data.get("csrf","")),str(session.get("csrf",""))): return jsonify(error="csrf"),400
    con=db(); con.execute("INSERT INTO progress(user_id,lesson_id,completed) VALUES(?,?,1) ON CONFLICT(user_id,lesson_id) DO UPDATE SET completed=1,updated_at=CURRENT_TIMESTAMP",(u["id"],n)); con.commit(); con.close()
    return jsonify(ok=True)

@APP.route("/register",methods=["GET","POST"])
def register():
    if request.method=="POST":
        require_csrf(); email=request.form.get("email","").strip().lower(); name=request.form.get("name","").strip(); pw=request.form.get("password",""); confirm=request.form.get("confirm_password","")
        if not rate_limit("register:"+request.remote_addr+":"+email,5,600): return layout('<div class="form"><div class="notice">Too many registration attempts. Try again in a few minutes.</div></div>'),429
        if len(name)<2 or len(name)>80 or not valid_email(email) or len(pw)<12 or len(pw)>128 or pw!=confirm:
            return layout('<div class="form"><div class="notice">Check your name, email, and password. Passwords must match and be 12–128 characters.</div><p><a href="/register">Try again</a></p></div>'),400
        try:
            con=db(); cur=con.execute("INSERT INTO users(email,name,password) VALUES(?,?,?)",(email,name,generate_password_hash(pw))); con.commit(); uid=cur.lastrowid; con.close(); session.clear(); session["uid"]=uid; session["csrf"]=secrets.token_urlsafe(24); return redirect("/dashboard")
        except sqlite3.IntegrityError:return layout('<div class="form"><div class="notice">That email is already registered.</div><p><a href="/login">Log in instead</a></p></div>'),409
    return layout(f'<form class="form" method="post" autocomplete="on"><h2>Create account</h2><p>Save progress across the course.</p><input type="hidden" name="csrf" value="{csrf()}"><label for="name">Name</label><input id="name" name="name" maxlength="80" autocomplete="name" required><label for="email">Email</label><input id="email" type="email" name="email" maxlength="254" autocomplete="email" required><label for="password">Password</label><input id="password" type="password" name="password" minlength="12" maxlength="128" autocomplete="new-password" required><label for="confirm_password">Confirm password</label><input id="confirm_password" type="password" name="confirm_password" minlength="12" maxlength="128" autocomplete="new-password" required><button>Create account</button></form>',"Create account")

@APP.route("/login",methods=["GET","POST"])
def login():
    if request.method=="POST":
        require_csrf(); email=request.form.get("email","").strip().lower(); pw=request.form.get("password","")
        if not valid_email(email) or len(pw)>128: return layout('<div class="form"><div class="notice">Invalid email or password.</div><p><a href="/login">Try again</a></p></div>'),401
        if not rate_limit("login:"+request.remote_addr+":"+email,8,600): return layout('<div class="form"><div class="notice">Too many login attempts. Try again in a few minutes.</div></div>'),429
        con=db(); u=con.execute("SELECT * FROM users WHERE email=?",(email,)).fetchone(); con.close()
        if not u or not check_password_hash(u["password"],pw): return layout('<div class="form"><div class="notice">Invalid email or password.</div><p><a href="/login">Try again</a></p></div>'),401
        session.clear(); session["uid"]=u["id"]; session["csrf"]=secrets.token_urlsafe(24); return redirect("/dashboard")
    return layout(f'<form class="form" method="post" autocomplete="on"><h2>Welcome back</h2><input type="hidden" name="csrf" value="{csrf()}"><label for="login-email">Email</label><input id="login-email" type="email" name="email" maxlength="254" autocomplete="email" required><label for="login-password">Password</label><input id="login-password" type="password" name="password" maxlength="128" autocomplete="current-password" required><button>Log in</button></form>',"Log in")

@APP.post("/logout")
def logout():
    require_csrf(); session.clear(); return redirect("/")

@APP.get("/dashboard")
def dashboard():
    u=user()
    if not u:return redirect("/login")
    con=db(); count=con.execute("SELECT COUNT(*) FROM progress WHERE user_id=? AND completed=1",(u["id"],)).fetchone()[0]; recent=con.execute("SELECT lesson_id,updated_at FROM progress WHERE user_id=? AND completed=1 ORDER BY updated_at DESC LIMIT 8",(u["id"],)).fetchall(); con.close()
    links="".join(f'<a class="lesson" href="/learn/{r["lesson_id"]}">Chapter {r["lesson_id"]} · {COURSE[r["lesson_id"]-1]["title"]}<span>→</span></a>' for r in recent) or '<p class="muted">Nothing completed yet. Start with Chapter 1.</p>'
    pct=round(count/len(COURSE)*100)
    return layout(f'<section class="course"><div class="eyebrow">Your dashboard</div><h1 style="font-size:60px">Keep going, {html.escape(str(u["name"]))}.</h1><div class="card"><div style="display:flex;justify-content:space-between"><strong>{count}/{len(COURSE)} lessons complete</strong><strong>{pct}%</strong></div><div class="bar" style="margin-top:12px"><i style="width:{pct}%"></i></div></div><h2>Recent progress</h2><div class="lessonlist">{links}</div></section>',"Dashboard")

@APP.get("/health")
def health(): return jsonify(status="ok",lessons=len(COURSE))

